import React, { useState, useEffect } from 'react';

// --- STYLES (To ensure the table looks like your screenshot) ---
const card = { background: 'white', padding: '24px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)', border: '1px solid #e2e8f0' };
const tableStyle = { width: '100%', borderCollapse: 'collapse', marginTop: '10px' };
const th = { textAlign: 'left', padding: '12px', fontSize: '13px', textTransform: 'uppercase', letterSpacing: '0.05em' };
const td = { padding: '12px', borderBottom: '1px solid #f1f5f9', fontSize: '14px' };
const sectionTitle = { fontSize: '18px', fontWeight: 700, color: '#1e293b', marginBottom: '16px' };

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  const statusColor = (s) => {
    const status = String(s).toLowerCase();
    if (status.includes('pass')) return '#10b981'; // Green
    if (status.includes('fail')) return '#ef4444'; // Red
    return '#f59e0b'; // Orange for In Progress
  };

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        setData(d);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <div style={{ padding: '40px', textAlign: 'center' }}>Loading Analytics...</div>;
  if (!data) return <div style={{ padding: '40px', color: 'red' }}>Backend Connection Failed</div>;

  // ✅ THE CRITICAL FIX: Standardize status for the filter
  const filteredUAVs = (data.uavs || []).filter(u => {
    if (filter === "ALL") return true;
    const uStatus = String(u.status || "").toLowerCase();
    const activeFilter = String(filter).toLowerCase();
    // Matches "Pass" with "Passed" and "Fail" with "Failed"
    return uStatus.includes(activeFilter.substring(0, 4));
  });

  return (
    <div style={{ padding: '30px', background: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ ...sectionTitle, fontSize: '24px' }}>Quality Analytics Dashboard</h2>

      {/* KPI Section */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
        {[
          { label: 'Total', val: data.total, type: 'ALL', color: '#64748b' },
          { label: 'Passed', val: data.passed, type: 'Pass', color: '#10b981' },
          { label: 'Failed', val: data.failed, type: 'Fail', color: '#ef4444' },
          { label: 'In Progress', val: data.inProgress, type: 'In Progress', color: '#f59e0b' }
        ].map(k => (
          <div 
            key={k.label} 
            onClick={() => setFilter(k.type)}
            style={{ 
              ...card, cursor: 'pointer', textAlign: 'center', 
              borderTop: `4px solid ${k.color}`,
              background: filter === k.type ? '#f1f5f9' : 'white'
            }}
          >
            <h1 style={{ margin: 0, color: k.color }}>{k.val}</h1>
            <p style={{ margin: 0, fontWeight: 600, color: '#64748b' }}>{k.label}</p>
          </div>
        ))}
      </div>

      {/* UAV List Section */}
      <div style={card}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <h3 style={{ ...sectionTitle, marginBottom: 0 }}>
            UAV List —&nbsp;
            <span style={{ color: filter === 'ALL' ? '#2563eb' : statusColor(filter) }}>
              {filter}
            </span>
            <span style={{ marginLeft: '10px', background: '#e2e8f0', borderRadius: '12px', padding: '2px 10px', fontSize: '13px', fontWeight: 600, color: '#334155' }}>
              {filteredUAVs.length}
            </span>
          </h3>
          {filter !== 'ALL' && (
            <button onClick={() => setFilter('ALL')} style={{ border: '1px solid #94a3b8', background: 'white', borderRadius: '6px', padding: '4px 12px', cursor: 'pointer', fontSize: '12px', color: '#475569' }}>
              Clear Filter ✕
            </button>
          )}
        </div>

        {filteredUAVs.length === 0 ? (
          <p style={{ color: '#94a3b8', fontSize: '14px', margin: 0, padding: '20px 0' }}>
            No UAVs with status "{filter}".
          </p>
        ) : (
          <table style={tableStyle}>
            <thead>
              <tr style={{ background: '#1e293b', color: 'white' }}>
                <th style={th}>#</th>
                <th style={th}>UAV ID</th>
                <th style={th}>Technician</th>
                <th style={th}>Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredUAVs.map((u, i) => (
                <tr key={u.id || i} style={{ background: i % 2 === 0 ? '#f8fafc' : 'white' }}>
                  <td style={{ ...td, color: '#94a3b8' }}>{i + 1}</td>
                  {/* ✅ KEY FIX: We use u.id because that's what the backend sends in analytics */}
                  <td style={{ ...td, fontWeight: 700 }}>{u.id || 'N/A'}</td>
                  <td style={td}>{u.techId || 'System'}</td>
                  <td style={td}>
                    <span style={{
                      background: statusColor(u.status) + '18',
                      color: statusColor(u.status),
                      border: `1px solid ${statusColor(u.status)}`,
                      borderRadius: '12px',
                      padding: '2px 12px',
                      fontWeight: 700,
                      fontSize: '12px',
                    }}>
                      {u.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export default Analytics;
